<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_student();$uid=(int)current_user()['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);db()->prepare('UPDATE users SET name=?,academic_year=?,monthly_allowance_baseline=?,monthly_savings_goal=? WHERE user_id=?')->execute([trim($_POST['name']),trim($_POST['academic_year']??'')?:null,($_POST['allowance']??'')===''?null:(float)$_POST['allowance'],($_POST['goal']??'')===''?null:(float)$_POST['goal'],$uid]);$_SESSION['user']['name']=trim($_POST['name']);flash('success','Profile updated.');redirect('student/profile.php');}$s=db()->prepare('SELECT * FROM users WHERE user_id=?');$s->execute([$uid]);$u=$s->fetch();$pageTitle='Profile';$activePage='profile';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">PROFILE</span><h1>Your profile</h1><p>Update the information used to personalize Campus Coin.</p></div></section><section class="panel form-panel"><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="profile-banner"><span class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></span><span><strong><?=e($u['name'])?></strong><small class="muted"><?=e($u['email'])?></small></span></div><label>Name<input class="input" name="name" value="<?=e($u['name'])?>" required></label><label>Email<input class="input" value="<?=e($u['email'])?>" disabled></label><div class="form-grid three"><label>Academic year<input class="input" name="academic_year" value="<?=e($u['academic_year'])?>"></label><label>Monthly allowance<input class="input" type="number" min="0" step="0.01" name="allowance" value="<?=e((string)$u['monthly_allowance_baseline'])?>"></label><label>Savings goal<input class="input" type="number" min="0" step="0.01" name="goal" value="<?=e((string)$u['monthly_savings_goal'])?>"></label></div><button class="btn btn-primary">Save profile</button></form